"""
ScholaCore Phase 2 -- student/teacher auth, teacher vetting, teacher
portal, admin dashboard, and the privacy/terms compliance pages.

Builds on the Phase 1 clean-slate scaffold already on `main`. This does
NOT delete anything -- it only adds the new pages/TS modules and updates
vite.config.ts (to register the new HTML entry points for the build) and
README.md (phase status).

Run on your Windows machine with the repo already cloned.

Usage:
    python deploy_scholacore_phase2.py [path_to_repo]
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    'student-signup.html': '',
    'teacher-vetting.html': '',
    'teacher-portal.html': '',
    'admin-dashboard.html': '',
    'privacy-policy.html': '',
    'terms-of-service.html': '',
    'src/types.ts': '',
    'src/pages/student-signup.ts': '',
    'src/pages/teacher-vetting.ts': '',
    'src/pages/teacher-portal.ts': '',
    'src/pages/admin-dashboard.ts': '',
    'vite.config.ts': '',
    'README.md': '',
}


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)
    if not os.path.isdir(os.path.join(repo_root, ".git")):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    written = []
    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_content))
        written.append(rel_path)
        print(f"wrote: {rel_path}")

    print(f"\n{len(written)} files written to {repo_root}")

    if not run(["git", "add"] + written, repo_root):
        sys.exit(1)
    commit_msg = "Phase 2: student/teacher auth, teacher vetting, teacher portal, admin dashboard, compliance pages"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)


if __name__ == "__main__":
    main()
